mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(a: &[i64]) -> bool { a.len() == 0 }

    #[effects(pure)]
    #[uses(witness, tasks::is_max_index)]
    fn refute(a: &[i64]) -> ()
        requires witness(a),
        ensures never(),
    {
        let r: usize = tasks::argmax(a);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        let e: [i64; 0] = [];
        refute(&e)
    }
